messages.content:
Write a single self-contained HTML file with a 3D animation using three.js. three.js r160 is available as an ES module at './three.module.js' -- import it with:
  import * as THREE from './three.module.js';
Scene: a low-poly 3D humanoid figure performs this exact cycle on a treadmill-style ground, side-on camera: stands still for 2 seconds, walks in place for 3 seconds (limbs swinging at walking pace), runs in place for 3 seconds (faster, larger limb swings, slight forward lean), then stands still again for 2 seconds. The 10-second cycle loops forever and must start immediately on load. Limb movement must clearly differ between walking and running. No external assets besides the three.js import. Output ONLY the HTML in one code block.

response.text:
```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Low Poly Humanoid Treadmill</title>
    <style>
        body { margin: 0; overflow: hidden; background-color: #111; }
        canvas { display: block; }
    </style>
</head>
<body>

<script type="module">
    import * as THREE from './three.module.js';

    // --- Configuration ---
    const CYCLE_DURATION = 10; // seconds
    const STATE_STILL = 0;
    const STATE_WALK = 1;
    const STATE_RUN = 2;

    // --- Scene Setup ---
    const scene = new THREE.Scene();
    scene.background = new THREE.Color(0x1a1a2e);
    scene.fog = new THREE.Fog(0x1a1a2e, 10, 50);

    const camera = new THREE.PerspectiveCamera(45, window.innerWidth / window.innerHeight, 0.1, 100);
    camera.position.set(0, 3, 12); // Side-on view
    camera.lookAt(0, 2, 0);

    const renderer = new THREE.WebGLRenderer({ antialias: true });
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.shadowMap.enabled = true;
    document.body.appendChild(renderer.domElement);

    // --- Lighting ---
    const ambientLight = new THREE.AmbientLight(0xffffff, 0.6);
    scene.add(ambientLight);

    const dirLight = new THREE.DirectionalLight(0xffffff, 1);
    dirLight.position.set(-5, 10, 5);
    dirLight.castShadow = true;
    dirLight.shadow.mapSize.width = 1024;
    dirLight.shadow.mapSize.height = 1024;
    scene.add(dirLight);

    // --- Materials ---
    const matBody = new THREE.MeshStandardMaterial({ color: 0x4ecca3, flatShading: true }); // Green
    const matHead = new THREE.MeshStandardMaterial({ color: 0xffeaa7, flatShading: true }); // Skin tone
    const matGround = new THREE.MeshStandardMaterial({ color: 0x0f0f1a, flatShading: true });
    const matTreadmill = new THREE.MeshStandardMaterial({ color: 0x333333, flatShading: true });
    const matBelt = new THREE.MeshStandardMaterial({ color: 0x111111, flatShading: true });

    // --- Geometry Construction (Low Poly Human) ---

    // Helper to create box mesh
    function createBox(w, h, d, mat, x, y, z) {
        const geo = new THREE.BoxGeometry(w, h, d);
        const mesh = new THREE.Mesh(geo, mat);
        mesh.position.set(x, y, z);
        mesh.castShadow = true;
        mesh.receiveShadow = true;
        return mesh;
    }

    // Root group for the character
    const character = new THREE.Group();
    scene.add(character);

    // 1. Torso
    const torso = createBox(1.2, 1.8, 0.8, matBody, 0, 0, 0);
    character.add(torso);

    // 2. Head
    const headPivot = new THREE.Group();
    headPivot.position.set(0, 1.1, 0); // Top of torso
    torso.add(headPivot);
    const head = createBox(0.9, 0.9, 0.9, matHead, 0, 0.45, 0);
    headPivot.add(head);

    // 3. Arms
    // Left Arm
    const leftArmPivot = new THREE.Group();
    leftArmPivot.position.set(-0.7, 0.7, 0); // Shoulder pos
    torso.add(leftArmPivot);
    const leftArm = createBox(0.4, 1.4, 0.4, matBody, 0, -0.7, 0);
    leftArmPivot.add(leftArm);

    // Right Arm
    const rightArmPivot = new THREE.Group();
    rightArmPivot.position.set(0.7, 0.7, 0); // Shoulder pos
    torso.add(rightArmPivot);
    const rightArm = createBox(0.4, 1.4, 0.4, matBody, 0, -0.7, 0);
    rightArmPivot.add(rightArm);

    // 4. Legs
    // Left Leg
    const leftLegPivot = new THREE.Group();
    leftLegPivot.position.set(-0.4, -0.9, 0); // Hip pos
    torso.add(leftLegPivot);
    const leftLeg = createBox(0.5, 1.6, 0.5, matBody, 0, -0.8, 0);
    leftLegPivot.add(leftLeg);

    // Right Leg
    const rightLegPivot = new THREE.Group();
    rightLegPivot.position.set(0.4, -0.9, 0); // Hip pos
    torso.add(rightLegPivot);
    const rightLeg = createBox(0.5, 1.6, 0.5, matBody, 0, -0.8, 0);
    rightLegPivot.add(rightLeg);


    // --- Environment ---

    // Ground Plane
    const groundGeo = new THREE.PlaneGeometry(100, 100);
    const ground = new THREE.Mesh(groundGeo, matGround);
    ground.rotation.x = -Math.PI / 2;
    ground.position.y = -2.5; // Feet level roughly
    ground.receiveShadow = true;
    scene.add(ground);

    // Treadmill Base
    const tmBase = new THREE.Group();
    tmBase.position.set(0, -2.5, 0);
    scene.add(tmBase);

    // Treadmill Frame
    const tmFrameFront = createBox(1, 1, 4, matTreadmill, 0, 0.5, 0);
    tmFrameFront.position.y = 0;
    tmBase.add(tmFrameFront);

    const tmFrameBack = createBox(1, 1, 4, matTreadmill, 0, 0.5, 0);
    tmFrameBack.position.set(0, 0, -4);
    tmBase.add(tmFrameBack);

    const tmConsole = createBox(1, 1, 0.5, matTreadmill, 0, 3, 0);
    tmConsole.position.set(0, 2, 2);
    tmBase.add(tmConsole);

    // --- Animation Logic ---

    const clock = new THREE.Clock();
    let time = 0;

    function animate() {
        requestAnimationFrame(animate);

        const delta = clock.getDelta();
        time += delta;

        // Cycle Logic
        // 0-2s: Still
        // 2-5s: Walk
        // 5-8s: Run
        // 8-10s: Still

        const cycleTime = time % CYCLE_DURATION;
        let state = STATE_STILL;
        let phase = 0; // 0 to 1 for the current action phase

        if (cycleTime < 2) {
            state = STATE_STILL;
        } else if (cycleTime < 5) {
            state = STATE_WALK;
            phase = (cycleTime - 2) / 3; 
        } else if (cycleTime < 8) {
            state = STATE_RUN;
            phase = (cycleTime - 5) / 3;
        } else {
            state = STATE_STILL;
        }

        // Smoothing transitions (optional, but makes it look better)
        // We will just apply values directly for snappy low-poly feel, 
        // but use Math.sin for the oscillation.

        const speed = state === STATE_WALK ? 3.0 : (state === STATE_RUN ? 6.0 : 0);
        const legAmp = state === STATE_WALK ? 0.6 : (state === STATE_RUN ? 1.2 : 0);
        const armAmp = state === STATE_WALK ? 0.6 : (state === STATE_RUN ? 1.0 : 0);
        const bodyLean = state === STATE_RUN ? 0.2 : 0;
        const bounce = state === STATE_WALK ? 0.1 : (state === STATE_RUN ? 0.25 : 0);

        // Calculate oscillation
        const t = time * speed;

        // Limb Animation
        // Left Leg: cos, Right Leg: -cos (opposite)
        leftLegPivot.rotation.x = Math.cos(t) * legAmp;
        rightLegPivot.rotation.x = -Math.cos(t) * legAmp;

        // Arms (opposite to legs)
        // Left Arm: -cos, Right Arm: cos
        leftArmPivot.rotation.x = -Math.cos(t) * armAmp;
        rightArmPivot.rotation.x = Math.cos(t) * armAmp;

        // Torso Lean & Bounce
        // Lean forward when running
        torso.rotation.x = -bodyLean; 

        // Vertical bounce (bobbing)
        // Math.abs(sin) creates a bounce every step
        character.position.y = Math.abs(Math.sin(t)) * bounce;

        // Head bob slightly
        headPivot.rotation.x = -Math.abs(Math.sin(t)) * (bounce * 0.5);

        renderer.render(scene, camera);
    }

    // Handle Window Resize
    window.addEventListener('resize', () => {
        camera.aspect = window.innerWidth / window.innerHeight;
        camera.updateProjectionMatrix();
        renderer.setSize(window.innerWidth, window.innerHeight);
    });

    // Start
    animate();

</script>
</body>
</html>
```
